        test("technical failures retain stack trace, cause chain and Git streams",()->{IOException disk=stackFixture();disk.addSuppressed(new IllegalStateException("suppressed detail"));Core.ObsException wrapped=new Core.ObsException(Core.STATE_DIVERGED,"wrapped failure",disk);String message=wrapped.getMessage();ok(message.contains("technical details"),"technical details marker missing");ok(message.contains("java.io.IOException: disk detail"),"wrapped cause was masked");ok(message.contains("at obs.rpkg.CoreTests.stackFixture"),"stack trace was masked");ok(message.contains("Caused by: java.lang.IllegalArgumentException: root detail"),"cause chain was masked");ok(message.contains("Suppressed: java.lang.IllegalStateException: suppressed detail"),"suppressed failure was masked");GitClient.Result bad=git.allow(repo,Core.FINALIZE_FAILED,"rev-parse","refs/heads/definitely-missing-ref");ok(bad.exitCode()!=0,"fixture Git command unexpectedly succeeded");String detail=bad.failureDetails();ok(detail.contains("command: git -C"),"Git command missing from details");ok(detail.contains("rev-parse refs/heads/definitely-missing-ref"),"Git args missing from details");ok(detail.contains("exitCode: "+bad.exitCode()),"Git exit code missing from details");ok(detail.contains("stderr:")||detail.contains("stdout:"),"Git process streams missing from details");});
