        test("Apply reports Repository Not Ready before mutation when repository has no first commit",()->{Path r=tmp.resolve("unborn-target");Files.createDirectories(r);g(r,"init","-b","main");g(r,"remote","add","origin",rawOrigin);Core c=new Core(new StateStore(tmp.resolve("unborn-state")));c.registerRepository("Unborn",r);PackageFixture p=makePackage(repoId,UUID.randomUUID().toString(),"unborn",List.of(op("x.txt","add",null,"x")));expect(Core.REPOSITORY_NOT_READY,()->c.applyPackage(p.path,r));ok(!Files.exists(r.resolve("x.txt")),"unborn Apply mutated target");});
        test("Apply target resolution preserves exact ChangeSet target and requires choice for new same-origin work",()->{Path a=tmp.resolve("resolve-a"),b=tmp.resolve("resolve-b");for(Path r:List.of(a,b)){Files.createDirectories(r);g(r,"init","-b","main");g(r,"config","user.name","OBS Test");g(r,"config","user.email","obs@example.invalid");write(r.resolve("x.txt"),"base");g(r,"add",".");g(r,"commit","-m","base");g(r,"remote","add","origin",rawOrigin);}Core c=new Core(new StateStore(tmp.resolve("resolve-state")));Core.RepositoryConfig ra=c.registerRepository("Resolve A",a),rb=c.registerRepository("Resolve B",b);String cs=UUID.randomUUID().toString();c.applyPackage(makePackage(repoId,cs,"existing",List.of(op("x.txt","replace","base","A"))).path,a);PackageFixture continuation=makePackage(repoId,cs,"existing",List.of(op("x.txt","replace","A","A2")));Core.ApplyTargetResolution exact=c.resolveApplyTarget("",continuation.path,rb.id());eq(exact.target().id(),ra.id(),"UI-current clone retargeted existing ChangeSet");PackageFixture fresh=makePackage(repoId,UUID.randomUUID().toString(),"new",List.of(op("new.txt","add",null,"new")));Core.ApplyTargetResolution ambiguous=c.resolveApplyTarget("",fresh.path,null);ok(ambiguous.target()==null&&ambiguous.candidates().size()==2,"same-origin clones were guessed for new work");});
        test("explicit repository location change preserves target identity and ChangeSet association",()->{Path a=tmp.resolve("move-a"),b=tmp.resolve("move-b");for(Path r:List.of(a,b)){Files.createDirectories(r);g(r,"init","-b","main");g(r,"config","user.name","OBS Test");g(r,"config","user.email","obs@example.invalid");write(r.resolve("x.txt"),"base");g(r,"add",".");g(r,"commit","-m","base");g(r,"remote","add","origin",rawOrigin);}Core c=new Core(new StateStore(tmp.resolve("move-state")));Core.RepositoryConfig target=c.registerRepository("Movable",a);String cs=UUID.randomUUID().toString();c.applyPackage(makePackage(repoId,cs,"move work",List.of(op("x.txt","replace","base","changed"))).path,a);Core.RepositoryConfig moved=c.changeRepositoryLocation(target.id(),b);eq(moved.id(),target.id(),"location change replaced Target ID");eq(c.repositoryForChangeSet(cs).id(),target.id(),"ChangeSet association changed during location edit");ok(Path.of(c.repositoryForChangeSet(cs).path()).equals(b.toAbsolutePath().normalize()),"ChangeSet did not follow mutable target location");});
        test("Finalized ChangeSet can be explicitly reopened safely and failed Reopen stays marker-free history",()->{Path r=tmp.resolve("reopen-repo"),remote=tmp.resolve("reopen-remote.git");Files.createDirectories(r);g(r,"init","-b","main");g(r,"config","user.name","OBS Test");g(r,"config","user.email","obs@example.invalid");g(r,"config","commit.gpgsign","false");write(r.resolve("x.txt"),"base");g(r,"add",".");g(r,"commit","-m","base");g(tmp,"init","--bare",remote.toString());g(r,"remote","add","origin",rawOrigin);g(r,"config","url."+remote.toUri()+".insteadOf",rawOrigin);Core c=new Core(new StateStore(tmp.resolve("reopen-state")));c.registerRepository("Reopen",r);String cs=UUID.randomUUID().toString();c.applyPackage(makePackage(repoId,cs,"reopen",List.of(op("x.txt","replace","base","after"))).path,r);c.finalizeChangeSet(cs,"final",r);eq(c.getChangeSet(cs).status,"Finalized","fixture not finalized");PackageFixture finalContinuation=makePackage(repoId,cs,"reopen",List.of(op("x.txt","replace","after","later")));expect(Core.STATE_DIVERGED,()->c.applyPackage(finalContinuation.path,r));Core.ChangeSet reopened=c.reopenChangeSet(cs);eq(reopened.status,"Active","Reopen did not activate same ChangeSet");eq(reopened.changeSetId,cs,"Reopen changed logical identity");ok(!reopened.finalizationHistory.isEmpty(),"Reopen lost finalization history");c.applyPackage(finalContinuation.path,r);c.finalizeChangeSet(cs,"final again",r);String sibling=UUID.randomUUID().toString();c.applyPackage(makePackage(repoId,sibling,"sibling",List.of(op("x.txt","replace","later","sibling"))).path,r);expect(Core.PATH_OWNERSHIP_CONFLICT,()->c.reopenChangeSet(cs));eq(c.getChangeSet(cs).status,"Finalized","ownership-conflict Reopen changed lifecycle");c.finalizeChangeSet(sibling,"sibling final",r);write(r.resolve("x.txt"),"manual-dirty");expect(Core.STATE_DIVERGED,()->c.reopenChangeSet(cs));Core.ChangeSet still=c.getChangeSet(cs);eq(still.status,"Finalized","failed Reopen changed lifecycle");ok(still.lastOperationStatus==null,"failed Reopen persisted Finalized error marker");g(r,"checkout","--","x.txt");});
        test("latest unfinished operation outcome persists across restart and later success clears the marker",()->{Path r=tmp.resolve("outcome-repo");Files.createDirectories(r);g(r,"init","-b","main");g(r,"config","user.name","OBS Test");g(r,"config","user.email","obs@example.invalid");write(r.resolve("x.txt"),"base");g(r,"add",".");g(r,"commit","-m","base");g(r,"remote","add","origin",rawOrigin);Path stateRoot=tmp.resolve("outcome-state");Core c=new Core(new StateStore(stateRoot));c.registerRepository("Outcome",r);String cs=UUID.randomUUID().toString();c.applyPackage(makePackage(repoId,cs,"outcome",List.of(op("x.txt","replace","base","changed"))).path,r);c.recordOperationOutcome(cs,"FAILED",Core.STATE_DIVERGED,"failure reason");Core reloaded=new Core(new StateStore(stateRoot));Core.ChangeSet failed=reloaded.getChangeSet(cs);ok(reloaded.hasFailedLatestOutcome(failed),"failed latest outcome did not persist");eq(failed.lastOperationMessage,"failure reason","failure reason did not persist");reloaded.recordOperationOutcome(cs,"SUCCESS",Core.SUCCESS,"recovered");ok(!new Core(new StateStore(stateRoot)).hasFailedLatestOutcome(new Core(new StateStore(stateRoot)).getChangeSet(cs)),"later success did not clear error marker meaning");});
        test("global work projection hides Finalized until history is requested",()->{Path r=tmp.resolve("projection-repo");Files.createDirectories(r);g(r,"init","-b","main");g(r,"config","user.name","OBS Test");g(r,"config","user.email","obs@example.invalid");write(r.resolve("x.txt"),"base");g(r,"add",".");g(r,"commit","-m","base");g(r,"remote","add","origin",rawOrigin);Path stateRoot=tmp.resolve("projection-state");Core c=new Core(new StateStore(stateRoot));c.registerRepository("Projection",r);String active=UUID.randomUUID().toString();c.applyPackage(makePackage(repoId,active,"active",List.of(op("x.txt","replace","base","changed"))).path,r);Core.ChangeSet historical=new Core.ChangeSet();historical.changeSetId=UUID.randomUUID().toString();historical.changeSetLabel="history";historical.repositoryIdentity=repoId;historical.repositoryTargetId=c.getRepositories().get(0).id();historical.repositoryRoot=r.toString();historical.status="Finalized";historical.createdAt=historical.updatedAt=java.time.Instant.now().toString();new StateStore(stateRoot).saveChangeSet(historical);ok(c.getGlobalChangeSets(false).stream().noneMatch(x->x.changeSetId.equals(historical.changeSetId)),"Finalized leaked into default projection");ok(c.getGlobalChangeSets(true).stream().anyMatch(x->x.changeSetId.equals(historical.changeSetId)),"History did not include Finalized");});
        test("global ChangeSet query tolerates unavailable Repository Target without substitution",()->{Path stateRoot=tmp.resolve("unavailable-target-state");StateStore st=new StateStore(stateRoot);Core c=new Core(st);Core.ChangeSet orphan=new Core.ChangeSet();orphan.changeSetId=UUID.randomUUID().toString();orphan.changeSetLabel="orphan active";orphan.repositoryIdentity=repoId;orphan.repositoryTargetId=UUID.randomUUID().toString();orphan.repositoryRoot=tmp.resolve("removed-repo").toString();orphan.status="Active";orphan.createdAt=orphan.updatedAt=java.time.Instant.now().toString();st.saveChangeSet(orphan);ok(c.getGlobalChangeSets(false).stream().anyMatch(x->x.changeSetId.equals(orphan.changeSetId)),"unavailable unfinished ChangeSet disappeared from global selector projection");ok(c.findRepositoryForChangeSet(orphan.changeSetId)==null,"query lookup silently substituted another Repository Target");expect(Core.REPOSITORY_MISMATCH,()->c.repositoryForChangeSet(orphan.changeSetId));});
        test("Git-equivalent continuation works for an owned file that is still untracked by HEAD",()->{Path r=tmp.resolve("untracked-owned-source");Files.createDirectories(r);g(r,"init","-b","main");g(r,"config","user.name","OBS Test");g(r,"config","user.email","obs@example.invalid");write(r.resolve(".gitattributes"),"owned-new.txt text\n");write(r.resolve("seed.txt"),"seed");g(r,"add",".");g(r,"commit","-m","base");g(r,"remote","add","origin",rawOrigin);Core c=new Core(new StateStore(tmp.resolve("untracked-owned-source-state")));c.registerRepository("Owned",r);String cs=UUID.randomUUID().toString();c.applyPackage(makePackage(repoId,cs,"owned",List.of(op("owned-new.txt","add",null,"line1\nline2\n"))).path,r);ok(g(r,"ls-files","--","owned-new.txt").joined().isBlank(),"fixture file unexpectedly tracked in HEAD/index");Files.writeString(r.resolve("owned-new.txt"),"line1\r\nline2\r\n",StandardCharsets.UTF_8);Core.ApplyResult continued=c.applyPackage(makePackage(repoId,cs,"owned",List.of(op("owned-new.txt","replace","line1\nline2\n","next\n"))).path,r);eq(continued.code(),Core.SUCCESS,"untracked-but-owned continuation was rejected");eq(read(r.resolve("owned-new.txt")),"next\n","continuation result wrong");});
        test("binary source divergence is rejected without newline normalization",()->{Path r=tmp.resolve("binary-source");Files.createDirectories(r);g(r,"init","-b","main");g(r,"config","user.name","OBS Test");g(r,"config","user.email","obs@example.invalid");String actual=String.valueOf((char)0)+"A",wrong=String.valueOf((char)0)+"X";Files.write(r.resolve("binary.dat"),actual.getBytes(StandardCharsets.UTF_8));g(r,"add",".");g(r,"commit","-m","base");g(r,"remote","add","origin",rawOrigin);Core c=new Core(new StateStore(tmp.resolve("binary-source-state")));c.registerRepository("Binary",r);PackageFixture p=makePackage(repoId,UUID.randomUUID().toString(),"binary",List.of(op("binary.dat","replace",wrong,String.valueOf((char)0)+"B")));expect(Core.SOURCE_STATE_CHANGED,()->c.applyPackage(p.path,r));ok(Arrays.equals(Files.readAllBytes(r.resolve("binary.dat")),actual.getBytes(StandardCharsets.UTF_8)),"binary divergence mutated target");});
        test("Git clean-filter failure makes source state unverifiable and fails closed",()->{Path r=tmp.resolve("filter-source");Files.createDirectories(r);g(r,"init","-b","main");g(r,"config","user.name","OBS Test");g(r,"config","user.email","obs@example.invalid");write(r.resolve("owned.txt"),"base\n");g(r,"add",".");g(r,"commit","-m","base");g(r,"remote","add","origin",rawOrigin);Core c=new Core(new StateStore(tmp.resolve("filter-source-state")));c.registerRepository("Filter",r);String cs=UUID.randomUUID().toString();c.applyPackage(makePackage(repoId,cs,"filter",List.of(op("owned.txt","replace","base\n","current\n"))).path,r);write(r.resolve(".gitattributes"),"owned.txt filter=broken\n");g(r,"config","filter.broken.clean","false");g(r,"config","filter.broken.required","true");Files.writeString(r.resolve("owned.txt"),"current\r\n",StandardCharsets.UTF_8);PackageFixture correction=makePackage(repoId,cs,"filter",List.of(op("owned.txt","replace","current\n","next\n")));expect(Core.SOURCE_STATE_UNVERIFIABLE,()->c.applyPackage(correction.path,r));eq(read(r.resolve("owned.txt")),"current\r\n","unverifiable source mutated target");});
